/* 导航项 */
.nav-item {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 120px;
  height: 56px;
  color: var(--menu-text-color, white);
  text-decoration: none;
  transition: background-color 0.3s;
}

.nav-item:hover {
  background-color: rgba(255, 255, 255, 0.1);
}

/* 激活的导航项直接使用主题色 */
.nav-item.active {
  background-color: var(--primary-color);
  color: #ffffff;
  font-weight: 500;
}

/* 导航文本 */
.nav-text {
  font-size: 18px;
  font-weight: 400;
  line-height: 1.5;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

tool_input.new_string:
/* 导航项 */
.nav-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 160px;
  height: 110px;
  gap: 4px;
  color: rgba(226, 239, 255, 0.82);
  text-decoration: none;
  transition: color 0.2s ease;
}

.nav-item::before {
  content: '';
  position: absolute;
  z-index: 0;
  top: 50%;
  left: 50%;
  width: 96px;
  height: 64px;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 13px;
  background: rgba(0, 81, 155, 0.76);
  box-shadow: 0 3px 10px rgba(0, 25, 63, 0.28);
  opacity: 0;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s ease;
  pointer-events: none;
}

.nav-item > * {
  position: relative;
  z-index: 1;
}

.nav-item:hover {
  color: #fff;
}

.nav-item:hover::before {
  opacity: 0.45;
}

.nav-item.active {
  background: transparent;
  color: #ffffff;
  font-weight: 500;
}

.nav-item.active::before {
  opacity: 1;
}

.nav-item__icon {
  display: block;
  width: 26px;
  height: 26px;
  flex: 0 0 26px;
  color: currentColor;
}

.nav-item__icon--custom {
  font-size: 26px;
}

/* 导航文本 */
.nav-text {
  font-size: 16px;
  font-weight: 400;
  line-height: 20px;
  max-width: none;
  overflow: visible;
  text-overflow: clip;
  white-space: nowrap;
}
